// Russian copy (ru-RU). Natural, formal-polite («вы») Russian for a women's health application — NOT a literal
// word-for-word rendering of en.ts. Same key set and the same interpolation placeholders as the other dictionaries.
//
// Plural keys: Russian has four cardinal forms. Every English `_one`/`_other` pair is expanded to
// `_one` (1, 21, 31…), `_few` (2–4, 22–24…), `_many` (0, 5–20, 25–30…) and `_other` (fractions). The form is chosen
// by i18next through Intl.PluralRules — and by src/i18n/pluralRules.ts on engines (Hermes) that do not have it.
//
// Conventions: «ёлочки» for quotation marks; the typed destructive-confirmation word is «УДАЛИТЬ»; the partner
// feature is «AWA Вместе»; language names are endonyms («Русский»). Religious-practice terms follow common Russian
// usage (намаз, пост/ураза, каза, нифас, истихада, гусль) and stay neutral and educational — the wording of the
// religious content still needs scholar validation, exactly as in the other languages.
